import sys

def main():
    max_total = -1
    result_name = ""

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split('#')
        if len(parts) >= 4:
            name = parts[0]
            try:
                mark1 = int(parts[1])
                mark2 = int(parts[2])
                mark3 = int(parts[3])
                total = mark1 + mark2 + mark3
                if total > max_total:
                    max_total = total
                    result_name = name
            except ValueError:
                continue

    print(result_name)

if __name__ == "__main__":
    main()
